"""
Pydantic models for tracking agent memory, history, and action requests.
"""

import uuid
from datetime import UTC, datetime
from typing import Any, Literal

from pydantic import BaseModel, Field


class ActionRequest(BaseModel):
    """Represents a planned action generated by the LLM."""

    thought: str = Field(..., description="The reasoning behind the chosen action")
    action: Literal["NAVIGATE", "CLICK", "TYPE", "EXTRACT", "FINISH"] = Field(
        ..., description="The action to perform"
    )
    parameters: dict[str, Any] = Field(
        default_factory=dict, description="Parameters required for the action"
    )


class ActionHistory(BaseModel):
    """A record of a completed action."""

    action: str
    parameters: dict[str, Any]
    url: str
    timestamp: datetime = Field(default_factory=lambda: datetime.now(UTC))


class AgentState(BaseModel):
    """The complete execution state of a Verboisy run."""

    run_id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    goal: str
    target_schema: dict[str, Any]
    history: list[ActionHistory] = Field(default_factory=list)
    extracted_data: list[dict[str, Any]] = Field(default_factory=list)
    status: Literal["INITIALIZED", "RUNNING", "COMPLETED", "FAILED"] = "INITIALIZED"
    current_url: str | None = None
    step_count: int = 0
    max_steps: int = 20
